SET ROLE talus_fn;
CREATE TABLE app.service_schedule(tenant_id uuid NOT NULL,service_schedule_id uuid NOT NULL,machine_id uuid NOT NULL,service_kind text NOT NULL,interval_hours integer,interval_miles integer,interval_days integer,last_service_hours integer,last_service_miles integer,last_service_at timestamptz,PRIMARY KEY(tenant_id,service_schedule_id),FOREIGN KEY(tenant_id,machine_id) REFERENCES app.machine(tenant_id,machine_id),CHECK(interval_hours IS NOT NULL OR interval_miles IS NOT NULL OR interval_days IS NOT NULL));
CREATE TABLE app.maintenance_block(tenant_id uuid NOT NULL,maintenance_block_id uuid NOT NULL,machine_id uuid NOT NULL,scheduled_by uuid NOT NULL,reason text NOT NULL,period tstzrange NOT NULL,status text NOT NULL CHECK(status IN('scheduled','in_progress','completed','cancelled')),PRIMARY KEY(tenant_id,maintenance_block_id),FOREIGN KEY(tenant_id,machine_id) REFERENCES app.machine(tenant_id,machine_id),FOREIGN KEY(tenant_id,scheduled_by) REFERENCES app.principal(tenant_id,principal_id));
CREATE TABLE app.work_order(tenant_id uuid NOT NULL,work_order_id uuid NOT NULL,machine_id uuid NOT NULL,maintenance_block_id uuid NOT NULL,technician_name text NOT NULL,labor_cents bigint NOT NULL CHECK(labor_cents>=0),parts_cents bigint NOT NULL CHECK(parts_cents>=0),notes text NOT NULL DEFAULT '',completed_at timestamptz,status text NOT NULL CHECK(status IN('draft','completed')),PRIMARY KEY(tenant_id,work_order_id),FOREIGN KEY(tenant_id,machine_id) REFERENCES app.machine(tenant_id,machine_id),FOREIGN KEY(tenant_id,maintenance_block_id) REFERENCES app.maintenance_block(tenant_id,maintenance_block_id));
CREATE TRIGGER m09_work_append BEFORE UPDATE OR DELETE ON app.work_order FOR EACH ROW EXECUTE FUNCTION app.enforce_append_only();
CREATE OR REPLACE FUNCTION app.schedule_maintenance_block(p_id uuid,p_machine uuid,p_period tstzrange,p_reason text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=app,pg_catalog AS $$ DECLARE t uuid:=app.current_context_tenant_id();BEGIN PERFORM app.require_staff_role('staff');INSERT INTO app.maintenance_block VALUES(t,p_id,p_machine,app.current_context_principal_id(),p_reason,p_period,'scheduled');INSERT INTO app.machine_occupancy(tenant_id,machine_id,maintenance_reference_id,occupancy_kind,occupancy_range)VALUES(t,p_machine,p_id,'maintenance',p_period);PERFORM app.append_audit('maintenance.scheduled','maintenance_block',p_id);RETURN p_id;END;$$;
CREATE OR REPLACE FUNCTION app.complete_work_order(p_id uuid,p_block uuid,p_machine uuid,p_tech text,p_labor bigint,p_parts bigint,p_debit uuid,p_credit uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=app,pg_catalog AS $$ DECLARE t uuid:=app.current_context_tenant_id();BEGIN PERFORM app.require_staff_role('staff');INSERT INTO app.work_order VALUES(t,p_id,p_machine,p_block,p_tech,p_labor,p_parts,'',clock_timestamp(),'completed');UPDATE app.machine_occupancy SET blocking=false WHERE tenant_id=t AND maintenance_reference_id=p_block;UPDATE app.maintenance_block SET status='completed' WHERE tenant_id=t AND maintenance_block_id=p_block;PERFORM app.post_journal_entry(gen_random_uuid(),'maintenance','work-'||p_id::text,p_debit,p_credit,p_labor+p_parts);PERFORM app.append_audit('maintenance.completed','work_order',p_id);RETURN p_id;END;$$;
DO $$ DECLARE x text;BEGIN FOREACH x IN ARRAY ARRAY['service_schedule','maintenance_block','work_order'] LOOP EXECUTE format('ALTER TABLE app.%I ENABLE ROW LEVEL SECURITY;ALTER TABLE app.%I FORCE ROW LEVEL SECURITY;CREATE POLICY tenant_context_policy ON app.%I USING(tenant_id=app.current_context_tenant_id() AND app.context_is_valid()) WITH CHECK(tenant_id=app.current_context_tenant_id() AND app.context_is_valid())',x,x,x);END LOOP;END;$$;
REVOKE ALL ON app.service_schedule,app.maintenance_block,app.work_order FROM PUBLIC,talus_staff,talus_api,talus_customer;
RESET ROLE;
